(window.FREALLY_I18N = window.FREALLY_I18N || {})["vi"] = {"hero.headline":"<span class=\"hl-muted\">Đặt lên mặt kính. Nhấn START.</span> <span class=\"cycle\" data-cycle=\"hero.cycle\">Kéo bản sao ra.</span>","hero.cycle":"Kéo bản sao ra.|Kéo MIDI ra.|Kéo âm thanh ra.","hero.sub":"Đưa âm thanh vào, MIDI ra. Đưa MIDI vào, âm thanh ra. Miễn phí, ngoại tuyến và 100% không dùng AI.","hero.chipStandalone":"Ứng dụng độc lập","what.title":"Đây là gì","what.p1":"Biến một đoạn loop thành MIDI, hay một tệp MIDI thành âm thanh, thường có nghĩa là một chuỗi công cụ, một lần xuất, nhập lại và rất nhiều phỏng đoán về kết quả.","what.p2":"Flipcopy là một máy photocopy. Đặt một tệp âm thanh hoặc tệp MIDI lên mặt kính của nó, nó sẽ in ra bản gốc — dạng sóng thật, hoặc từng nốt nhạc cùng dữ liệu của nó. Nhấn nút START màu xanh lá, nó sẽ in ra bản sao ở dạng còn lại: đưa âm thanh vào, MIDI ra; đưa MIDI vào, âm thanh ra.","what.p3":"Bản sao ra dưới dạng một trang in với khung xanh chanh quanh đoạn clip. Cầm lấy khung và kéo nó vào một track trong DAW của bạn. Mỗi bản sao là một tệp thật, nằm nguyên tại chỗ, nên dự án của bạn không bao giờ mất nó.","see.title":"Xem nó sao chép","see.intro":"Máy photocopy, được dựng hình bằng Blender: bản gốc đặt xuống mặt kính, nắp đóng lại, đèn quét qua, và bản sao trượt ra khay.","see.start":"Nhấn START để xem máy sao chép","see.audioToMidi":"Đưa âm thanh vào, MIDI ra: mỗi lớp một trang — giai điệu, hợp âm, bassline và giai điệu đối.","see.midiToAudio":"Đưa MIDI vào, âm thanh ra.","features.title":"Bên trong có gì","features.copier.title":"Máy photocopy","features.copier.body":"Một máy photocopy được dựng hình chân thực bằng Blender. Đặt một clip lên mặt kính, nó sẽ in ra thứ thật: từng nốt nhạc, hoặc dạng sóng thật, cùng tempo, độ dài và mức âm lượng.","features.start.title":"Nút START màu xanh lá","features.start.body":"Thả một clip xuống chỉ đặt nó lên mặt kính. Không gì được sao chép cho đến khi bạn nhấn START, nên không có gì xảy ra ngoài ý muốn của bạn.","features.audioToMidi.title":"Âm thanh → MIDI","features.audioToMidi.body":"Trống, bass, giai điệu, giai điệu đối và hợp âm trong một loop, mỗi thứ một trang, in liền nhau từ một lần quét, để kéo vào DAW thành các track riêng.","features.midiToAudio.title":"MIDI → âm thanh","features.midiToAudio.body":"Một tệp MIDI được chơi qua một nhạc cụ thật, và trống qua một drum machine, in ra thành một tệp âm thanh bạn có thể kéo đi.","features.drag.title":"Kéo bản sao","features.drag.body":"Mỗi trang mang một khung xanh chanh quanh clip của nó. Cầm lấy và thả vào một track. Tệp là thật, và Flipcopy không bao giờ ghi đè hay xóa nó.","features.browser.title":"Trình duyệt","features.browser.body":"Một trình duyệt tệp có trình phát để nghe thử, từ Freally Oscillate. Nó hiện dạng sóng cho âm thanh và các nốt nhạc cho MIDI, và phát MIDI qua đúng nhạc cụ mà bản sao sử dụng.","features.daw.title":"Trong mọi DAW","features.daw.body":"CLAP, VST3 và AU, cùng một ứng dụng độc lập để làm việc không cần DAW và cho Pro Tools. Windows, macOS và Linux.","features.free.title":"Miễn phí, ngoại tuyến, không dùng AI","features.free.body":"Không có gói, không tài khoản, không đo lường từ xa, không mạng, không mô hình. Xử lý tín hiệu cổ điển, được một cổng kiểm tra khi dựng bảo đảm chứ không chỉ là lời hứa.","docs.language.title":"Ngôn ngữ","docs.language.p1":"Flipcopy nói được mười tám ngôn ngữ. Nó khởi động bằng ngôn ngữ hệ thống của bạn; để chọn ngôn ngữ khác, mở Cài đặt bằng biểu tượng bánh răng ở đầu trình duyệt và chọn một ngôn ngữ. Lựa chọn này áp dụng cho mọi bản Flipcopy trên máy tính.","ladder.title":"Con đường đến 1.0","ladder.intro":"Mỗi phiên bản một dòng. Đây là chính chiếc thang mà kế hoạch nội bộ đang theo — nếu một bên di chuyển, bên kia cũng di chuyển, và một cổng kiểm tra khi dựng sẽ đối chiếu chúng.","ladder.rung.v0.1.0":"Nền móng: plugin tải được dưới dạng CLAP, VST3 và AU lẫn ứng dụng độc lập, cho âm thanh của bạn đi qua nguyên vẹn, đề nghị bạn chấp nhận giấy phép, và mọi cổng kiểm tra chất lượng đều chạy.","ladder.rung.v0.2.0":"Máy photocopy và bản sao đầu tiên: cỗ máy trong cửa sổ, nút START màu xanh lá, và một tệp MIDI được sao thành âm thanh để bạn kéo thẳng vào DAW.","ladder.rung.v0.3.0":"Âm thanh sang MIDI: đặt một loop lên mặt kính, nhấn START, rồi kéo trống, bass, giai điệu và hợp âm của nó ra dưới dạng MIDI.","ladder.rung.v0.4.0":"Trình duyệt tệp và trình phát nghe thử: tìm một sample hoặc clip MIDI, nghe, xem, rồi kéo nó lên mặt kính. Mọi thứ thiết yếu đều đã có.","ladder.rung.v0.5.0":"Màn hình cảm ứng: thiết lập sao chép, nhạc cụ cho các bản sao, định dạng tệp, và lịch sử của mọi bản sao bạn đã tạo.","ladder.rung.v0.5.5":"Studio: mở bất kỳ bản sao nào trong piano roll, sửa các nốt, nghe bằng bất kỳ nhạc cụ nào, và in bản chỉnh sửa thành một bản sao mới.","ladder.rung.v0.5.7":"Bàn trộn và nhạc cụ của riêng bạn: núm vặn chân thực để định hình từng phần, bộ trống và sample của riêng bạn, mục yêu thích, và một thư viện nhạc cụ dùng chung cho mọi ứng dụng Freally.","ladder.rung.v0.5.9":"Giao diện và chế độ sáng: năm giao diện, mỗi cái là một khung nổi được dựng bằng Blender và giống nhau trên mọi ứng dụng Freally, có bản sáng và tối, cùng một chế độ sáng mới.","ladder.rung.v0.6.0":"Trong mọi DAW: lưu cùng dự án, nhiều bản sao cùng lúc, quét trực tiếp từ một track, và được kiểm tra trên từng DAW.","ladder.rung.v0.7.0":"Ứng dụng độc lập với đầy đủ sức mạnh, macOS và Linux, cùng video máy photocopy đang hoạt động.","ladder.rung.v0.8.0":"Độ chính xác, độ chân thực và tốc độ: ký âm tốt hơn, cỗ máy thuyết phục hơn, và mọi ngân sách hiệu năng đều được thực thi.","ladder.rung.v1.0.0-beta":"Gia cố: trình cài đặt cho ba hệ điều hành, tính năng kiểm tra cập nhật tùy chọn, và cuốn sổ tay minh họa đầy đủ. Trang này vẫn chưa có bản tải xuống.","ladder.rung.v1.0.0-rc":"Bản ứng viên phát hành: mọi tệp đều được rà soát và mọi host đều được thử thủ công.","ladder.rung.v1.0.0":"Bản phát hành chính thức — và những bản tải xuống đầu tiên trang này từng cung cấp.","ladder.rung.v1.1.0":"Khay nạp bản gốc: sao chép cả một thư mục trong một lần.","ladder.rung.v1.3.0":"Bản sao dạng bản nhạc: MusicXML và bản in trên khuông nhạc.","ladder.rung.v1.4.0":"Cầu nối đến các sản phẩm Freally khác.","ladder.rung.v1.5.0":"Pro Tools dưới dạng plugin (AAX), nếu điều khoản của Avid cho phép với một sản phẩm miễn phí.","ladder.rung.v1.6.0":"Bản sao groove, và bản sao stem thô, không dùng AI.","ladder.note":"Một phiên bản hoàn tất đã được dựng và gắn thẻ. Đó không phải là bản tải xuống: chưa có, và sẽ không có cho đến 1.0.0.","honest.title":"Những điều mà hầu hết các trang web đặt ở cuối trang","honest.transcription.title":"Bản sao MIDI của một bản mix là một bản ký âm","honest.transcription.body":"Tìm nốt nhạc trong một bản mix đã hoàn thiện là việc khó, và Flipcopy làm điều đó bằng xử lý tín hiệu cổ điển thay vì một mô hình. Nó sẽ bỏ sót một số nốt và nghe ra một số nốt không thật sự có. Nó in ra những gì tìm được, và nói rõ những gì nó không làm được.","honest.chords.title":"Hợp âm quay lại dưới dạng một tiến trình hợp âm","honest.chords.body":"Một bè hợp âm được in ra như tiến trình hợp âm mà nó theo, chứ không phải cách bấm chính xác đã được chơi, và trang in nói rõ điều đó.","honest.downloads.title":"Chưa có bản tải xuống nào trước 1.0.0","honest.downloads.body":"Không có bản beta trên trang này, không có bản dựng thử, không có quyền truy cập sớm. Một máy photocopy chạy nửa vời còn tệ hơn một máy chưa tồn tại.","honest.network.title":"Nó không bao giờ lên mạng","honest.network.body":"Plugin và ứng dụng độc lập hoàn toàn không chứa mã mạng nào, và một cổng kiểm tra khi dựng sẽ thất bại nếu có mã như vậy được thêm vào. Một phiên bản sau này có thể thêm một tính năng kiểm tra cập nhật, mặc định tắt trừ khi bạn tự bật lên, được chạy bởi một chương trình riêng biệt.","site.tagline":"Đặt lên mặt kính. Nhấn START. Kéo bản sao ra.","footer.licence":"Phần mềm độc quyền — Bảo lưu mọi quyền. © Mike Weaver. Hiện miễn phí sử dụng; các phiên bản sau này có thể được bán. Không phải mã nguồn mở.","footer.yours":"Những bản sao bạn tạo ra là của bạn, miễn là các tệp bạn sao chép vốn thuộc quyền sử dụng của bạn. Tác giả của Flipcopy không nhận bất kỳ quyền sở hữu nào đối với chúng.","featuresPage.lead":"Một máy photocopy cho các clip của bạn. Đưa âm thanh vào, MIDI ra, tách thành từng phần; đưa MIDI vào, âm thanh ra, qua nhạc cụ thật — và mọi bản sao đều kéo thẳng được vào DAW của bạn.","featuresPage.version":"Trang này mô tả Freally Flipcopy phiên bản 1.0: mọi thứ trên trang đều có trong 1.0, và không có gì dự kiến cho sau 1.0 xuất hiện ở đây.","featuresPage.numbers.directions":"chiều: âm thanh → MIDI và MIDI → âm thanh","featuresPage.numbers.parts":"loại phần nó sao chép: trống, bass, giai điệu, giai điệu đối, hợp âm và một dòng giọng hát","featuresPage.numbers.instruments":"nhạc cụ để chơi một bản sao MIDI","featuresPage.numbers.bars":"ô nhịp: loop dài nhất mà mặt kính nhận","featuresPage.numbers.formats":"định dạng tệp nó ghi ra: MIDI, WAV, AIFF, FLAC và MP3","featuresPage.numbers.plugins":"định dạng plugin, cùng một ứng dụng độc lập","featuresPage.numbers.systems":"hệ điều hành: Windows, macOS và Linux","featuresPage.numbers.languages":"ngôn ngữ","featuresPage.numbers.ai":"mô hình AI","featuresPage.numbers.price":"giá hiện nay","featuresPage.free.title":"Hiện miễn phí","featuresPage.free.body":"Mọi thứ Flipcopy làm hiện nay đều miễn phí cho tất cả mọi người: không có gói trả phí, không thuê bao, không tài khoản và không có bản dùng thử hết hạn. Những bản sao bạn tạo ra là của bạn, miễn là các tệp bạn sao chép vốn thuộc quyền sử dụng của bạn.","featuresPage.cards.title":"Phiên bản 1.0 làm được gì","featuresPage.cards.copier.title":"Máy photocopy","featuresPage.cards.copier.body":"Một máy photocopy được dựng hình chân thực bằng Blender, với âm thanh riêng của nó. Đặt một clip lên mặt kính, nó sẽ in ra thứ thật — dạng sóng, hoặc từng nốt nhạc — cùng dữ liệu của nó: tempo, độ dài, nốt nhạc hoặc mức âm lượng.","featuresPage.cards.start.title":"Chỉ nút START màu xanh lá mới sao chép","featuresPage.cards.start.body":"Thả một clip xuống chỉ đặt nó lên mặt kính. Không gì được sao chép cho đến khi bạn nhấn START; STOP hủy một lần quét và HOME dọn mặt kính, nên không có gì xảy ra ngoài ý muốn của bạn.","featuresPage.cards.audioToMidi.title":"Âm thanh → MIDI, theo từng phần","featuresPage.cards.audioToMidi.body":"Một loop được tách ra thành các phần bên trong nó — trống trên các làn riêng, bass, giai điệu, giai điệu đối nếu có, và tiến trình hợp âm — mỗi phần một trang và một tệp MIDI, từ một lần quét duy nhất. Phần nào không có thì không có trang. Hoặc sao chép riêng một dòng giọng hát.","featuresPage.cards.midiToAudio.title":"MIDI → âm thanh, qua nhạc cụ thật","featuresPage.cards.midiToAudio.body":"Một tệp MIDI được chơi qua bất kỳ nhạc cụ nào trong số 1,648 nhạc cụ mà Freally MIDI Master dùng — một âm sắc cho mỗi phần và một drum machine cho trống — và được in thành mỗi phần một trang âm thanh, cộng thêm toàn bộ bản mix. WAV, AIFF, FLAC hoặc MP3, ở tần số mẫu và độ sâu bit bạn chọn.","featuresPage.cards.drag.title":"Kéo bản sao","featuresPage.cards.drag.body":"Mỗi trang mang một khung xanh chanh: cầm lấy nó và thả tệp vào một track. Hoặc kéo cả chồng — Tất cả phần thành mỗi phần một track, Bản mix đầy đủ thành một clip. Mỗi tệp được đặt tên theo cách DAW của bạn nên hiển thị, chẳng hạn Loop - Bassline - 120 BPM - C# Minor.","featuresPage.cards.copies.title":"Bản sao còn mãi","featuresPage.cards.copies.body":"Mỗi bản sao là một tệp thật, đã được xác minh, trong thư mục Bản sao của bạn — được đánh số, và không bao giờ bị di chuyển, ghi đè hay xóa, nên dự án nào dùng nó cũng không bao giờ mất nó. Lật lại từng bản sao bạn đã tạo, lưu lại một bản, hiện nó trong thư mục, hoặc đặt nó trở lại mặt kính.","featuresPage.cards.browser.title":"Trình duyệt và trình phát nghe thử","featuresPage.cards.browser.body":"Một trình duyệt tệp từ Freally Oscillate: tối đa 128 thư mục, lùi và tiến, thẻ, gắn sao và điều hướng bằng bàn phím. Phần nghe thử hiện dạng sóng thật hoặc các nốt nhạc, phát MIDI bằng đúng âm sắc mà bản sao dùng, và phát đồng bộ cả một chồng đã hoàn tất, kèm so sánh A/B với bản gốc.","featuresPage.cards.studio.title":"Studio","featuresPage.cards.studio.body":"Mở bất kỳ bản sao nào trong piano roll, mỗi phần một tab, chỉnh sửa y hệt như trong Freally MIDI Master. Nghe nó qua bất kỳ nhạc cụ nào, định hình nó trên bàn trộn với núm vặn chân thực, chơi nó qua bộ trống của riêng bạn hoặc một sample của bạn, rồi gửi bản chỉnh sửa trở lại mặt kính để in thành một bản sao mới.","featuresPage.cards.settings.title":"Thiết lập trên màn hình cảm ứng","featuresPage.cards.settings.body":"Màn hình riêng của máy photocopy chứa các thiết lập sao chép: những phần nào, lưới và swing, tempo và nguồn của nó, âm sắc cho từng phần, định dạng tệp và phần đuôi. Một cổng kiểm tra khi dựng xác nhận rằng mỗi thiết lập thực sự thay đổi bản sao.","featuresPage.cards.daw.title":"Trong mọi DAW","featuresPage.cards.daw.body":"CLAP và VST3 trên Windows, macOS và Linux, AU trên macOS, và một ứng dụng độc lập để làm việc không cần DAW — và cho Pro Tools, bằng cách kéo thả. Được lưu cùng dự án, an toàn khi mở nhiều bản cùng lúc, và có thể quét trực tiếp từ một track.","featuresPage.cards.skins.title":"Giao diện, sáng và tối","featuresPage.cards.skins.body":"Năm giao diện, mỗi cái là một khung nổi được dựng bằng Blender và dùng chung cho mọi ứng dụng Freally, có bản sáng và tối, bên cạnh chế độ sáng và tối đơn giản. Máy photocopy được dựng hình lại cho từng giao diện, nên nó luôn đứng trên nền của chính nó.","featuresPage.cards.offline.title":"Ngoại tuyến, riêng tư, không dùng AI","featuresPage.cards.offline.body":"Không đo lường từ xa và không mô hình. Mọi bản sao đều được tạo bằng xử lý tín hiệu cổ điển, và plugin cùng ứng dụng không bao giờ lên mạng. Ngoại lệ duy nhất là tính năng kiểm tra cập nhật, mặc định tắt trừ khi bạn tự bật lên, được chạy bởi một chương trình riêng biệt.","featuresPage.compare.title":"Đặt cạnh các công cụ thương mại","featuresPage.compare.intro":"Freally Flipcopy 1.0 đặt cạnh các công cụ thương mại mà nhà sản xuất nhạc dùng để biến âm thanh thành MIDI và MIDI thành âm thanh. Mọi ô của sản phẩm khác đều lấy từ chính các trang của nhà sản xuất sản phẩm đó, được kiểm tra ngày 1 tháng 10 năm 2026, và giá là giá niêm yết tại Mỹ tính đến tháng 10 năm 2026.","featuresPage.compare.feature":"Tính năng","featuresPage.compare.row.price":"Giá (USD, tháng 10 năm 2026)","featuresPage.compare.freeToday":"Hiện miễn phí","featuresPage.compare.row.audioToMidi":"Biến âm thanh thành MIDI","featuresPage.compare.legend.yes":"có","featuresPage.compare.row.parts":"Tách một loop thành các phần, mỗi phần một tệp MIDI riêng","featuresPage.compare.legend.no":"không","featuresPage.compare.note.byPitch":"tách nốt, không tách nhạc cụ","featuresPage.compare.note.byInstrument":"theo nhạc cụ","featuresPage.compare.legend.partly":"một phần","featuresPage.compare.note.byHand":"tách stem trước, rồi làm thủ công từng cái","featuresPage.compare.row.midiToAudio":"Biến MIDI thành âm thanh qua nhạc cụ tích hợp","featuresPage.compare.legend.unknown":"chưa xác minh","featuresPage.compare.note.playbackOnly":"phát được, nhưng không xuất âm thanh","featuresPage.compare.row.drag":"Kéo kết quả thẳng vào một track của DAW","featuresPage.compare.note.ara":"trong một số DAW, qua ARA","featuresPage.compare.row.plugin":"Chạy trong DAW dưới dạng plugin","featuresPage.compare.note.link":"gửi âm thanh sang ứng dụng riêng của nó","featuresPage.compare.note.ownDaw":"chỉ trong DAW của chính nó","featuresPage.compare.note.appOnly":"chỉ là ứng dụng độc lập","featuresPage.compare.row.systems":"Windows, macOS và Linux","featuresPage.compare.row.noAi":"Không dùng AI hay học máy","featuresPage.compare.note.aiStems":"dùng nó để tách stem","featuresPage.compare.summaryTitle":"Tóm lại","featuresPage.compare.summary":"Nói ngắn gọn: chỉ Flipcopy có đủ tất cả — cả hai chiều, các phần, thao tác kéo, plugin, cả ba hệ điều hành và không AI.","featuresPage.compare.theyWinTitle":"Họ hơn ở đâu","featuresPage.compare.theyWin":"Chỗ họ hơn: Melodyne Studio, RipX, AnthemScore và Ableton Live có thể viết ra từng nốt riêng của một hợp âm từ một bản thu đa âm (Melodyne chỉ làm được với một nhạc cụ thu riêng); Flipcopy thay vào đó đưa cho bạn tiến trình hợp âm, và nói rõ điều đó. RipX, Ableton Live Suite và Logic Pro còn tách một bản mix thành các stem âm thanh, điều mà Flipcopy 1.0 không làm.","featuresPage.compare.asOf":"Cột của Flipcopy là phiên bản 1.0, vốn chưa ra mắt, và giá của nó là giá hiện nay: Flipcopy hiện miễn phí, và các phiên bản sau này có thể được bán. Các sản phẩm khác cũng thay đổi; bảng này cập nhật đến ngày 1 tháng 10 năm 2026.","featuresPage.why.title":"Vì sao nó được làm như vậy","featuresPage.why.dsp.title":"Xử lý tín hiệu cổ điển","featuresPage.why.dsp.body":"Phát hiện điểm bắt đầu nốt, dò cao độ, chroma và một bộ dựng âm xác định, không có mô hình ở bất cứ đâu. Cùng một tệp, cùng thiết lập và cùng phiên bản luôn cho ra cùng một bản sao, giống đến từng byte, mọi lần.","featuresPage.why.print.title":"Thấy gì thì kéo nấy","featuresPage.why.print.body":"Mỗi trang được vẽ từ chính các byte của tệp mà nó kéo theo. Các nốt, tempo và độ dài trên giấy chính là các nốt, tempo và độ dài sẽ nằm trên track của bạn.","featuresPage.why.honest.title":"Bản sao trung thực","featuresPage.why.honest.body":"Không có trang trống và không có phỏng đoán đội lốt bản ký âm. Hợp âm nói rõ chúng là một tiến trình, một clip quá dài so với mặt kính sẽ bị từ chối kèm độ dài của nó thay vì bị cắt, và một dòng giọng hát được để nguyên sẽ nói rõ điều đó.","featuresPage.why.local.title":"Mọi thứ ở lại trên máy của bạn","featuresPage.why.local.body":"Không đo lường từ xa và không đám mây. Tệp và bản sao của bạn không bao giờ rời khỏi máy tính của bạn, và một cổng kiểm tra khi dựng sẽ thất bại nếu mã mạng từng được thêm vào plugin hay ứng dụng.","featuresPage.why.tempo.title":"Nó đi theo DAW của bạn","featuresPage.why.tempo.body":"Plugin đọc tempo của dự án và không bao giờ thay đổi nó, và mọi tempo mà Flipcopy in ra đều ghi rõ nguồn gốc: loop, tệp, tên tệp, DAW của bạn, hoặc chính bạn.","featuresPage.why.mix.title":"Không gì lọt vào bản mix của bạn một cách vô tình","featuresPage.why.mix.body":"Âm thanh của máy photocopy và phần nghe thử phát nhỏ qua plugin, và không bao giờ vào bản bounce. Khi chúng im lặng, âm thanh của track bạn đi qua nguyên vẹn.","featuresPage.coming.title":"Những gì vẫn đang đến","featuresPage.coming.intro":"Nói thẳng, vì một danh sách tính năng giấu đi các thiếu sót thì không đáng đọc. Trang này mô tả phiên bản 1.0, và Flipcopy được xây từng nấc một: không phải mọi thứ trên trang đã được làm xong. Mỗi nấc trên con đường đến 1.0 đều được đánh dấu trạng thái.","featuresPage.limits.title":"Những gì 1.0 không làm","featuresPage.limits.chords":"Nó không viết ra từng nốt của một hợp âm nghe được trong một bản thu đã mix: hợp âm quay lại dưới dạng tiến trình, và trang in nói rõ điều đó.","featuresPage.limits.loops":"Nó sao chép loop, không phải cả bài hát: mặt kính nhận clip dài tối đa 16 ô nhịp, và từ chối clip dài hơn kèm độ dài của nó.","featuresPage.limits.stems":"Nó không tách một bản thu đã mix thành các stem âm thanh: các phần của một loop ra dưới dạng MIDI.","featuresPage.limits.aax":"Nó không phải plugin Pro Tools: trong Pro Tools, hãy dùng ứng dụng độc lập và kéo bản sao vào dòng thời gian.","featuresPage.coming.downloads":"Không có bản tải xuống nào trước phiên bản 1.0, và cũng không có trên trang này.","docs.intro":"Tài liệu này lớn dần theo từng phiên bản. Hiện nó mô tả những gì phiên bản 0.4.0 làm được; tài liệu minh họa đầy đủ, có ảnh chụp cho từng bước, sẽ có cùng bản beta.","docs.start.title":"Bắt đầu","docs.agreement.title":"Thỏa thuận cấp phép","docs.window.title":"Cửa sổ","docs.copier.title":"Tạo một bản sao","docs.browser.title":"Trình duyệt","docs.preview.title":"Trình phát nghe thử","docs.report.title":"Khi có sự cố","docs.privacy.title":"Quyền riêng tư và mạng","docs.start.p1":"Flipcopy chạy bên trong DAW của bạn như một plugin CLAP, VST3 hoặc AU, hoặc chạy riêng như một ứng dụng độc lập. Đặt nó lên bất kỳ track âm thanh nào: nó cho âm thanh của track đi qua nguyên vẹn đúng như khi đến, nên để nó ở nguyên chỗ là an toàn.","docs.start.p2":"Chưa có bản tải xuống nào trước phiên bản 1.0.0, và mã nguồn là riêng tư.","docs.agreement.p1":"Lần đầu mở, Flipcopy hiện ra thỏa thuận cấp phép của nó. Đọc đến hết, nút Đồng ý sẽ khả dụng. Cho đến khi bạn đồng ý, Flipcopy không đọc gì, không sao chép gì và không thêm gì vào âm thanh của track bạn.","docs.agreement.p2":"Câu trả lời của bạn được lưu trên máy tính của bạn và dùng chung cho mọi bản Flipcopy đang mở, trong mọi DAW và trong ứng dụng độc lập. Nếu bạn từ chối, hãy chọn Đọc lại bất cứ khi nào bạn sẵn sàng.","docs.window.p1":"Một bên là trình duyệt, với trình phát nghe thử neo bên dưới nó. Phần còn lại của cửa sổ là sân khấu, nơi máy photocopy đứng. Kéo đường phân cách giữa chúng để làm trình duyệt rộng hơn hay hẹp hơn, hoặc chọn nó rồi dùng các phím mũi tên.","docs.window.p2":"Nhấn Ctrl+B (Cmd+B trên Mac), hoặc nút ở mép trình duyệt, để thu gọn trình duyệt cùng phần nghe thử: sân khấu chiếm trọn cửa sổ. Nhấn lần nữa, chúng trở lại với độ rộng lúc bạn để lại. Flipcopy ghi nhớ lựa chọn của bạn.","docs.copier.p1":"Đặt một tệp âm thanh hoặc MIDI lên mặt kính: thả nó từ Explorer hoặc Finder vào bất cứ đâu trong cửa sổ, kéo nó từ trình duyệt hoặc dải nghe thử lên máy photo, nhấn Enter trên một hàng trong trình duyệt, hoặc nhấn Enter trên mặt kính trống để chọn một tệp. Máy photo in bản gốc và úp nó xuống mặt kính. Đặt một tệp lên mặt kính không bao giờ bắt đầu sao chép.","docs.copier.p2":"Nhấn phím START màu xanh, hoặc Ctrl+Enter (Cmd+Enter trên Mac). Nắp đóng lại, đèn quét, và bản sao trượt ra khay: một loop âm thanh ra thành MIDI, mỗi phần mà máy photo nghe thấy là một trang; một tệp MIDI ra thành âm thanh, mỗi phần một trang. Esc hoặc phím STOP màu đỏ hủy nó; phím HOME màu xám dọn mặt kính.","docs.copier.p3":"Mỗi trang là một tệp thật trong Documents/Freally Flipcopy/Copies, được đánh số, và không bao giờ bị di chuyển, ghi đè hay xóa. Nắm một trang vào khung màu xanh chanh quanh clip đã in của nó và kéo thẳng lên một track trong DAW của bạn, hoặc kéo cả chồng cùng lúc.","docs.copier.p4":"Tiếng của máy photo phát nhỏ qua ngõ ra riêng của plugin, không bao giờ khi DAW đang phát và không bao giờ vào bản bounce. Tắt hoặc giảm chúng trong Cài đặt.","docs.browser.p1":"Trình duyệt mở ở phần Danh mục: Bản sao, mọi trang và bản mix bạn đã tạo, và Gần đây, những bản gốc bạn đặt lên mặt kính gần nhất. Bên dưới là các thư mục bạn đã thêm; chọn + Thêm thư mục để thêm một thư mục, tối đa 128. Một thư mục trên ổ đĩa đang không được cắm vẫn giữ chỗ của nó và báo rằng hiện không được kết nối. Để ngừng duyệt một thư mục, nhấp chuột phải vào nó, hoặc chọn nó rồi nhấn Delete; không có gì trên ổ đĩa bị động đến.","docs.browser.p2":"Mở một thư mục để duyệt nó như một cây. Gõ để lọc theo tên, chọn một thẻ hoặc Đã gắn sao để thu hẹp, và chọn Hiện mọi tệp để xem các tệp đi kèm mà Flipcopy ẩn đi, như .asd và .reapeaks. Quay lại và Tiến tới đưa bạn qua những nơi bạn đã đến.","docs.browser.p3":"Đi qua các hàng bằng ↑ và ↓: mỗi hàng bạn dừng lại sẽ phát một lần trong phần nghe thử. → mở một thư mục và ← đóng nó lại. Enter đặt tệp đã chọn lên mặt kính, và kéo hàng của nó lên máy photo cũng vậy.","docs.browser.p4":"Lần đầu bạn thêm một thư mục, Flipcopy đếm các tệp của nó, với một thanh cho thấy đã đi được bao xa. Nó đọc sâu tối đa 12 cấp thư mục và tối đa 50.000 tệp, và không bao giờ đi theo một lối tắt ra khỏi thư mục.","docs.preview.p1":"Trình phát nghe thử nằm dưới trình duyệt. Một tệp âm thanh hiện dạng sóng thật của nó. Một tệp MIDI hiện các nốt nhạc và phát qua Preview Piano, cùng âm sắc mà bản sao dùng trừ khi bạn chọn âm sắc khác, nên bạn nghe được bản sao sẽ nghe ra sao.","docs.preview.p2":"Phím cách phát và tạm dừng, Dừng quay về đầu, còn một cú nhấp hoặc kéo trên dải sẽ di chuyển đầu phát. Lặp lại phát lặp tệp, Phát khi chọn (biểu tượng tai nghe) phát mỗi tệp bạn chọn, và thanh trượt chỉnh mức âm lượng. Phần nghe thử phát qua ngõ ra riêng của Flipcopy và không bao giờ vào bản bounce. Tệp WAV dài bao nhiêu cũng phát được; tệp ở định dạng khác phát được nếu dài năm phút trở xuống.","docs.preview.p3":"Nhấp vào bản gốc trên mặt kính, hoặc một trang trên khay, để nghe nó. Khi bản sao đã xong, Bản sao phát tất cả các trang của nó cùng lúc và Bản gốc phát tệp trên mặt kính, từ cùng một vị trí trong bản nhạc, để bạn nghe ra sự khác biệt trước khi kéo. Không bao giờ bắt buộc phải nghe: các trang có thể kéo ngay khi trang cuối cùng nằm yên.","docs.preview.p4":"Dải nghe thử mang cùng khung xanh chanh như một trang. Kéo nó lên mặt kính để đặt tệp đó lên đấy.","docs.report.p1":"Nếu chính Flipcopy gặp lỗi, chẳng hạn một bản sao nó không ghi được, màn hình sẽ đưa ra Báo cáo. Nút này mở một trang trong trình duyệt web của bạn cho thấy chính xác báo cáo chứa gì; không có gì được gửi đi trừ khi bạn nhấn Gửi ở đó. Một tệp bị máy photo từ chối vì quá dài, im lặng hoặc không phải âm thanh thì không phải là lỗi, và thay vào đó màn hình sẽ nói lý do.","docs.privacy.p1":"Flipcopy không có tài khoản, không có đo lường từ xa, và plugin cùng ứng dụng độc lập hoàn toàn không chứa mã mạng nào. Tệp và bản sao của bạn không bao giờ rời khỏi máy tính của bạn.","docs.privacy.p2":"Nó không chứa bất kỳ dạng AI nào: mọi bản sao đều được tạo ra bằng xử lý tín hiệu cổ điển, xác định, và một cổng kiểm tra khi dựng sẽ thất bại nếu có thư viện học máy nào từng được thêm vào.","kit.skip":"Chuyển đến nội dung","kit.nav.site":"Trang web","kit.nav.home":"Trang chủ","kit.nav.features":"Tính năng","kit.nav.documentation":"Tài liệu","kit.nav.changelog":"Nhật ký thay đổi","kit.nav.language":"Ngôn ngữ","kit.nav.allApps":"Tất cả ứng dụng Freally","kit.badge.progress":"v0.4.0 đã xong · tiếp theo là v0.5.0","kit.cta.features":"Xem mọi tính năng","kit.cta.docs":"Đọc tài liệu","kit.price":"Freally Flipcopy hiện miễn phí, nhưng có thể không miễn phí mãi mãi: các phiên bản sau này có thể được bán.","kit.noDownloads":"Hiện chưa có bản tải xuống, và mã nguồn là riêng tư.","kit.label.overview":"Tổng quan","kit.label.inAction":"Khi hoạt động","kit.label.inside":"Bên trong","kit.label.roadmap":"Lộ trình","kit.ladder.done":"Xong","kit.ladder.planned":"Đã lên kế hoạch","kit.ladder.goal":"Mục tiêu","kit.ladder.later":"Về sau","kit.label.honesty":"Trung thực","kit.family.label":"Gia đình Freally","kit.family.title":"<span class=\"hl-muted\">Một gia đình.</span> <span class=\"hl-bright\">Tám ứng dụng.</span>","kit.cta.label":"Những gì đã thay đổi","kit.cta.title":"<span class=\"hl-muted\">Mỗi phiên bản,</span> <span class=\"hl-bright\">đều được ghi lại.</span>","kit.cta.lede":"Nhật ký thay đổi liệt kê mọi thứ đã thay đổi trong Freally Flipcopy, theo từng phiên bản, bằng cả mười tám ngôn ngữ.","kit.cta.changelog":"Đọc nhật ký thay đổi","kit.footer.thisApp":"Ứng dụng này","kit.footer.family":"Gia đình Freally","kit.status.devVersion":"Đang phát triển · v0.4.0","kit.head.features":"<span class=\"hl-muted\">Mọi thứ nó làm được,</span> <span class=\"hl-bright\">đặt cạnh nhau.</span>","kit.label.numbers":"Qua các con số","kit.numbers.lead":"Mỗi con số đều được đếm từ chính ứng dụng. Không có gì là ước tính, và không có gì được làm tròn lên.","kit.label.free":"Miễn phí hôm nay","kit.label.compare":"So sánh","kit.label.principles":"Nguyên tắc","kit.label.limits":"Giới hạn","kit.states.title":"Ý nghĩa của các trạng thái","kit.states.done":"đã dựng và gắn thẻ, nhưng không phải bản tải xuống trên trang này","kit.states.planned":"vẫn chưa được xây dựng","kit.states.goal":"phiên bản mà con đường này hướng tới","kit.states.later":"sau đó, và chưa được lên lịch","kit.states.ladder":"Xem mọi nấc trên con đường","kit.head.documentation":"<span class=\"hl-muted\">Cách hoạt động,</span> <span class=\"hl-bright\">từng bước một.</span>","kit.search.placeholder":"Tìm kiếm trong tài liệu","kit.docs.contents":"Mục lục","kit.head.changelog":"<span class=\"hl-muted\">Mọi thay đổi,</span> <span class=\"hl-bright\">theo từng phiên bản.</span>","kit.changelog.lede":"Mới nhất trước: mọi thứ đã thay đổi trong Freally Flipcopy, bằng mọi ngôn ngữ của trang này.","kit.changelog.versions":"Phiên bản","kit.search.none":"Không có gì trên trang này khớp với điều đó.","changelog.b0befc5e6040":"<span class=\"release__meta\"><span class=\"release__ver\">v0.4.0</span><time class=\"release__date\" datetime=\"2026-10-05\">2026-10-05</time></span><span class=\"release__title\">Trình duyệt tệp và trình phát nghe thử</span>","changelog.e884ffe2f90e":"Tìm một sample hoặc một clip MIDI, nghe nó, xem nó và đặt nó lên mặt kính — trình duyệt và trình phát nghe thử từ Freally Oscillate, bên cạnh máy photo. Mọi thứ thiết yếu đã có: MVP đã hoàn chỉnh.","changelog.6b02e0d363a4":"Đã thêm","changelog.130b73a201db":"<strong>Trình duyệt.</strong> Nó mở ở phần Danh mục — <strong>Bản sao</strong>, mọi trang và bản mix bạn đã tạo, và <strong>Gần đây</strong>, những bản gốc bạn đặt lên mặt kính gần nhất, mỗi mục đều có số đếm — rồi đến các thư mục bạn thêm bằng <strong>+ Thêm thư mục</strong> (tối đa 128). Một thư mục trên ổ đĩa đã rút ra vẫn giữ chỗ và báo điều đó; nhấp chuột phải vào một thư mục, hoặc chọn nó rồi nhấn <code>Delete</code>, để ngừng duyệt nó, và không có gì trên ổ đĩa bị động đến. <strong>Quay lại</strong> và <strong>Tiến tới</strong> đi qua những nơi bạn đã đến, y hệt như trong Freally Oscillate.","changelog.3c76294f691c":"<strong>Thư mục dạng cây.</strong> Mở rộng và thu gọn nó, gõ để lọc, thu hẹp theo một thẻ hoặc theo các mục gắn sao của bạn, và chọn <strong>Hiện mọi tệp</strong> để xem các tệp đi kèm mà nó ẩn đi (<code>.asd</code>, <code>.reapeaks</code> và những tệp tương tự). <code>↑</code>/<code>↓</code> đi qua các hàng và mỗi hàng bạn dừng lại sẽ phát một lần; <code>→</code> mở một thư mục, <code>←</code> đóng nó, và <code>Enter</code> đặt tệp lên mặt kính.","changelog.9e19fd75f5c5":"<strong>Lập chỉ mục bạn có thể theo dõi.</strong> Một thư mục mới được đếm trên một luồng riêng với một thanh cho thấy đã đi được bao xa — sâu tối đa 12 cấp thư mục và 50.000 tệp, không bao giờ đi theo một lối tắt ra khỏi thư mục.","changelog.7e5083732503":"<strong>Trình phát nghe thử</strong>, neo dưới trình duyệt. Âm thanh hiện dạng sóng thật của nó; một tệp MIDI hiện các nốt nhạc và phát qua <strong>Preview Piano</strong>, đúng âm sắc và cách render mà bản sao dùng, nên phần nghe thử chính là bản sao. <code>Space</code> phát và tạm dừng; nhấp hoặc kéo trên dải để di chuyển đầu phát, vốn đếm đến nốt cuối cùng của bản nhạc chứ không bao giờ đến vạch nhịp; có lặp lại, phát khi chọn và mức âm lượng. Một tệp WAV dài bao nhiêu cũng được phát trực tiếp; định dạng khác phát được nếu dài năm phút trở xuống. Nó phát qua ngõ ra riêng của plugin và không bao giờ vào bản bounce.","changelog.ca065d9e7b42":"<strong>Nghe bản sao trước khi nó đi.</strong> Nhấp vào bản gốc trên mặt kính hoặc bất kỳ trang nào trên khay để nghe thử; khi bản sao đã xong, <strong>Bản sao</strong> phát mọi trang cùng lúc và <strong>Bản gốc</strong> phát mặt kính, từ cùng một vị trí trong bản nhạc. Tùy chọn: các trang kéo được ngay khi trang cuối cùng nằm yên, dù đã nghe hay chưa.","changelog.d17537ff40ec":"<strong>Kéo lên mặt kính.</strong> Một hàng, hoặc dải nghe thử — được đóng khung cùng màu xanh chanh như một trang —, khi kéo lên máy photo sẽ đặt tệp đó lên mặt kính, với một bản in nhỏ của nó đi theo con trỏ. Không có gì bắt đầu trước START.","changelog.cda58c5f73eb":"<strong>Ẩn trình duyệt</strong> bằng <code>Ctrl+B</code> (<code>Cmd+B</code> trên Mac) hoặc nút ở mép của nó: sân khấu chiếm trọn cửa sổ và tiêu đề xoay được căn giữa lại. Flipcopy ghi nhớ điều đó.","changelog.5d236e4be21d":"<strong>Báo cáo sự cố, ngay từ ứng dụng.</strong> Khi chính Flipcopy gặp lỗi, màn hình đưa ra <strong>Báo cáo</strong>; nút này mở trang báo cáo trong trình duyệt web của bạn, cho thấy chính xác nó chứa gì; không có gì được gửi đi trừ khi bạn nhấn Gửi ở đó.","changelog.2a6141e43be0":"Đã thay đổi","changelog.49de87a64bae":"<strong>Trang tài liệu</strong> được dựng từ bộ công cụ trang web dùng chung của Freally, giống nhau trên mọi trang Freally, với tài liệu hướng dẫn được cập nhật cho phiên bản này.","changelog.1246fc93bca0":"Đã sửa","changelog.b0f81c543dda":"<strong>Trang nằm dưới con trỏ được tìm thấy ở mọi kích thước cửa sổ.</strong> Một cú nhấp hoặc kéo trên một trang từng rơi sai chỗ khi cửa sổ được thu phóng.","changelog.2096d3c4bbd8":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-10-01\">2026-10-01</time></span><span class=\"release__title\">Âm thanh → MIDI: khoảnh khắc kỳ diệu</span>","changelog.df6f06284fdc":"Đặt một loop âm thanh lên mặt kính, nhấn START, và MIDI của nó sẽ ra — mỗi lớp mà máy photo nghe thấy là một trang, in liền nhau từ một lần quét, mỗi trang là một tệp riêng, đóng khung xanh chanh và kéo vào DAW của bạn riêng lẻ hoặc tất cả cùng lúc. Một tệp MIDI có nhiều phần cũng ra theo cách đó: mỗi phần một trang âm thanh, và toàn bộ tệp thành một bản mix.","changelog.24a7fe5481b4":"<strong>Âm thanh → MIDI.</strong> Một loop âm thanh được tách thành các lớp — trống, bass, giai điệu, một <strong>đối điệu</strong> khi loop có dòng thứ hai độc lập, và hợp âm — bằng bộ trích xuất DSP cổ điển của MIDI Master (không AI). Mỗi lớp tìm thấy là một trang riêng và một tệp <code>.mid</code> riêng, đặt tên theo cách DAW hiển thị (<em>Loop - Bassline - 120 BPM - C# Minor</em>); lớp nào không có thì không có trang, và một loop hoàn toàn không có nốt nào sẽ bị từ chối thay vì sao ra trang trắng. Giọng chỉ được in khi đọc được rõ ràng.","changelog.0c3d252fc872":"<strong>Một xấp trang.</strong> Các trang lần lượt được đẩy ra từ cùng một lần quét, xòe ra trên khay, mỗi trang mang tiêu đề là dạng và phần của nó (<em>MIDI GIAI ĐIỆU</em>, <em>ÂM THANH DÒNG BASS</em>) cùng <em>TRANG n/N</em>. Nhấp vào một trang để đưa nó lên trên cùng. <strong>Chưa thể kéo gì cho đến khi trang cuối cùng đã nằm yên.</strong>","changelog.55fa665ebb50":"<strong>Hai kiểu kéo từ xấp trang đã xong.</strong> Trang trên cùng có hai thẻ xanh chanh: <strong>Tất cả phần</strong> kéo mọi trang thành các tệp riêng, để DAW xếp chúng thành mỗi lớp một track; <strong>Bản mix đầy đủ</strong> kéo một tệp chứa tất cả — một tệp <code>.mid</code> nhiều track gồm mọi phần, hoặc toàn bộ bản kết xuất dưới dạng <code>.wav</code> — được ghi cạnh các trang và không bao giờ được in. Di chuột lên thẻ để xem thông số của bản mix; khi không có con trỏ, <em>Lưu bản phối đầy đủ thành…</em> sẽ lưu nó.","changelog.7ab067eeb165":"<strong>MIDI → âm thanh, từng phần một.</strong> Một tệp MIDI có nhiều phần sẽ in mỗi phần một trang âm thanh (<em>ÂM THANH GIAI ĐIỆU</em>, <em>ÂM THANH DÒNG BASS</em>), mỗi trang được kết xuất riêng và vẽ từ tệp WAV của chính nó, cùng với Bản mix đầy đủ — tổng các phần bằng đúng bản mix, dưới cùng một mức gain headroom.","changelog.71cfe75f90c6":"<strong>Loop dài tối đa 16 ô nhịp.</strong> Mặt kính từ chối clip dài hơn và cho biết độ dài của nó tính bằng ô nhịp, không bao giờ cắt ngắn; loop một, hai hoặc bốn ô nhịp vẫn được sao chép. Số ô nhịp của một loop âm thanh được đếm theo nhịp độ mà máy photo đọc được.","changelog.6aed786b024a":"<strong>Những trang trung thực.</strong> Trang Hợp âm nói rõ đó là vòng hòa âm, không phải cách bấm đã chơi; khi có một giai điệu hát được nghe thấy và để nguyên, trang đầu tiên nói rõ điều đó, và một loop chỉ có giai điệu hát sẽ bị từ chối kèm đúng lý do ấy, chứ không phải “không có gì để sao chép”. Mọi nhịp độ được in đều ghi rõ nguồn gốc — đọc từ loop, hoặc, khi các nhát đánh của loop không khớp lưới nào, là của host, của tên tệp hoặc mặc định.","changelog.cb05cd0fc0f0":"<strong><code>flipc</code></strong>, công cụ dòng lệnh, chạy chính mặt kính và máy photo của plugin: <code>flipc copy &lt;file&gt; --out &lt;dir&gt;</code>, <code>flipc facts &lt;file&gt;</code> (khối dữ liệu đúng như trang giấy in ra), <code>flipc score</code> (bộ chấm điểm corpus) và <code>flipc bench</code> (đo thời gian).","changelog.d2365b73e8bc":"<strong>Cổng kiểm tra corpus.</strong> Corpus audioTest được chấm điểm trong mỗi lần chạy CI cục bộ có nó — và báo SKIPPED ở nơi không có — so với các mức sàn chỉ tăng lên.","changelog.d2a673b21c8f":"<strong>Nhịp độ của host được theo dõi theo từng khối</strong>, và một tệp MIDI không có nhịp độ riêng sẽ được sao chép theo nhịp độ của host ngay lúc bạn nhấn START.","changelog.ee270218636c":"<strong>Nhịp độ của phiên chỉ dùng để phá thế hòa quãng tám.</strong> Một loop 120 BPM thả vào phiên 90 BPM được đọc ở 120 (bốn ô nhịp), chứ không phải 90 (ba ô nhịp) — đã sửa trong bộ trích xuất dùng chung của MIDI Master, cho mọi sản phẩm Freally có đọc loop.","changelog.ab8ac52d964e":"<strong>Hiện miễn phí, không hứa hẹn mãi mãi.</strong> Freally Flipcopy hiện miễn phí, nhưng có thể không miễn phí mãi mãi: các phiên bản sau này có thể được bán. Giờ đây mọi trang của trang tài liệu đều nói rõ điều này.","changelog.7fb464e21cf8":"<strong>Kho mã đã chuyển</strong> sang tài khoản GitHub riêng của người bảo trì, ở chế độ riêng tư và Bảo lưu mọi quyền, với các crate Freally dùng chung lấy từ Freally MIDI Master và Freally Oscillate bên cạnh; địa chỉ web của plugin là địa chỉ mới của trang tài liệu.","changelog.c584da8d5dfd":"<strong>Tích hợp liên tục chạy trên máy của người bảo trì</strong> trước mỗi lần push — mọi cổng kiểm tra trên Windows, và các cổng Linux trong Docker Desktop — và không có gì chạy trên GitHub Actions. Mọi commit đều mang <code>[skip ci]</code>. (Trong vài giờ vào ngày 2026-09-30, kho mã nguồn từng công khai và CI chạy trên GitHub cho mỗi lần push.)","changelog.79a07e8925af":"<strong>Giao diện có hồ sơ trình duyệt riêng.</strong> Dữ liệu WebView2 của Flipcopy (<code>%APPDATA%\\Freally Flipcopy\\webview</code>) trước đây bị lưu trong thư mục của Freally MIDI Master, và hai sản phẩm dùng chung một hồ sơ WebView2 có thể khiến giao diện của nhau bị trống khi cả hai chạy trong cùng một DAW. Giờ đây nó thuộc riêng Flipcopy.","changelog.72de476110e3":"<strong>Bản mix đầy đủ của một bản sao chỉ có thể là tệp của chính nó</strong>: một <code>record.json</code> bị sửa sau lưng máy photo không thể trỏ thao tác kéo, Lưu thành hay Hiện trong thư mục đến bất kỳ chỗ nào khác.","changelog.427549a6dab4":"<strong>Một bản sao được ghi trọn vẹn hoặc không ghi gì cả.</strong> Mọi trang và bản mix đều nằm trên đĩa trước khi bất kỳ tệp nào nhận tên của nó, nên một lỗi giữa chừng không bao giờ để lại các trang trong một thư mục đánh số mà không bản sao nào sở hữu.","changelog.2604a6288e96":"<strong>Không trang nào bị clip.</strong> Mức gain headroom duy nhất được xác định theo mọi tệp mà một bản sao ghi ra — một phần có thể có đỉnh cao hơn bản mix ở chỗ các phần khác triệt tiêu nó.","changelog.c6cb2c38dd63":"<strong>Một loop 16 ô nhịp được xuất dài thừa một tick vẫn là 16 ô nhịp</strong>, không phải 17 — một nốt cuối được nhả quá vạch nhịp một nốt móc ba không phải là một ô nhịp riêng.","changelog.2ba628500475":"<strong>Controller đến được trang in</strong> ngay cả trên một kênh không phát nốt nào.","changelog.833039ba4e85":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-09-30\">2026-09-30</time></span><span class=\"release__title\">Máy photocopy và bản sao đầu tiên</span>","changelog.35409a92a233":"Máy photo đứng trên sân khấu, diễn lại các phân cảnh của những video câu chuyện máy photo dựng bằng Blender theo đúng thứ tự: thả một tệp MIDI lên mặt kính, nhấn START màu xanh lá, và một bản sao âm thanh thật trượt ra khay — in từ chính tệp của nó, đóng khung xanh chanh, và kéo thẳng vào DAW của bạn.","changelog.c12f4045ef96":"<strong>Máy photo trên sân khấu.</strong> Cỗ máy được kết xuất từ cùng cảnh Blender với hai video câu chuyện — phần đế, nắp máy dưới dạng các khung sprite, các phím được nhấn, các matte của mặt kính và khay — được kết xuất trên chính nền của cửa sổ (<code>#090c09</code>) trên phim trong suốt, nên nó đứng trong căn phòng mà không có đường nối nào. Các giai đoạn là các phân cảnh của video theo đúng thứ tự trong video (tờ giấy lật lại và úp xuống, nắp máy đóng lại kèm cú nảy, tiếng bíp START, đèn quét qua lại, rò ánh xanh lơ ra khe phía trước trong khi cả căn phòng tối dần, bản sao trượt ra khay), với thời lượng ngắn hơn của bản cắt trong ứng dụng; một bài kiểm thử sẽ thất bại nếu ứng dụng phát một phân cảnh mà câu chuyện không có, bỏ qua một phân cảnh, hoặc phát sai thứ tự. Nó lấp đầy mọi khoảng trống mà cửa sổ dành cho nó và không bao giờ bị lật gương trong ngôn ngữ viết từ phải sang trái.","changelog.81d392181aa1":"<strong>Nút START xanh lá là cách kích hoạt duy nhất.</strong> Thả một clip chỉ đặt nó lên mặt kính. START (hoặc <code>Ctrl/Cmd+Enter</code>, nhấn đúng phím đó) bắt đầu sao chép; STOP (hoặc <code>Esc</code>) hủy giữa lúc quét mà không để lại gì; HOME dọn mặt kính. Phím mang chữ <em>START</em> đặt xiên, quay về phía bảng cảm ứng, và đèn LED của nó sáng mỗi khi có thể bắt đầu sao chép. Một bài kiểm thử plugin gửi mọi lệnh và thất bại nếu bất kỳ lệnh nào ngoài <code>copier_start</code> khởi động một tác vụ, và một cổng kiểm tra khi dựng sẽ thất bại nếu trang từng gửi lệnh đó từ bất cứ đâu ngoài phím START.","changelog.3c73db8b1385":"<strong>Mặt kính.</strong> Thả một tệp âm thanh hoặc MIDI từ Explorer hoặc Finder vào bất cứ đâu trên cửa sổ (mặt kính sáng lên khi tệp tới), hoặc nhấn <code>Enter</code> trên mặt kính trống để chọn một tệp. Tệp được đọc trên một luồng riêng và được in ngửa trước khi đặt xuống — nốt thật hoặc dạng sóng thật, cùng thông số riêng của tệp. Đường dẫn mạng, tệp quá lớn, quá dài, im lặng, bị hỏng, tính giờ SMPTE và tệp MIDI định dạng 2 đều bị từ chối, mỗi loại bằng một câu riêng. Hai tệp cùng lúc: tệp đầu tiên được đặt lên, và máy báo mỗi lần chỉ một clip. Một clip mới thả lên một bản sao đã xong cũng được đặt lên mặt kính như vậy, và khay được dọn trống (bản sao vẫn nằm trong thư mục Bản sao). Một tệp bị mặt kính từ chối sẽ để nguyên clip đang nằm trên đó.","changelog.4267b3fd96ac":"<strong>MIDI → âm thanh.</strong> Bản sao kết xuất các nốt của tệp qua một toner mặc định — chính các tiếng preset của MIDI Master cho các phần có cao độ, và một drum machine, mỗi làn GM một tiếng, cho phần trống — tôn trọng pitch bend và pedal sustain (của kênh nào chỉ áp dụng cho nốt của kênh đó), với đuôi 2.5 s, theo nhịp độ của tệp (nếu không có thì của host — ứng dụng độc lập không có — nếu không thì nhịp độ trong tên tệp, nếu không nữa thì 120 — và trang in ghi rõ là nguồn nào), giữ dưới −0.3 dBFS, và ghi thành tệp WAV 24-bit ở tần số mẫu của host (44.1 kHz trong ứng dụng độc lập) mà DAW đặt khớp lưới phách. Một bản sao dài tối đa bằng độ dài mà một trang có thể in — năm phút, hoặc 2:30 khi trên 48 kHz — và bản dài hơn sẽ bị từ chối trước khi kết xuất, không bao giờ bị cắt ngắn. Âm thanh → MIDI sẽ đến ở <code>v0.3.0</code>; trước đó, nhấn START với một clip âm thanh sẽ được báo thẳng thắn như vậy.","changelog.d9714ba71fa5":"<strong>Thư mục Bản sao</strong> (<code>Documents/Freally Flipcopy/Copies</code>): mỗi bản sao một thư mục đánh số, được giành một cách nguyên tử để hai DAW không bao giờ dùng chung một số; các trang được đặt tên theo cách DAW hiển thị (<code>Title - Part - 120 BPM, Key.wav</code>); mọi trang đều được ghi nguyên tử, đọc lại và xác minh — và <strong>không bao giờ bị di chuyển, ghi đè hay xóa</strong>, vì DAW của bạn tham chiếu nó qua đường dẫn.","changelog.48b3f94d470b":"<strong>Bản in, từ chính các tệp.</strong> Mọi trang — bản gốc trên mặt kính và bản sao trong khay — đều được in laser giống các bản in trong video câu chuyện: tiêu đề, dòng nguồn, thước ô nhịp, piano roll với làn lực nhấn hoặc dạng sóng với <strong>dải phổ</strong> mới, và khối dữ liệu, tất cả đều do plugin tính từ các byte trên đĩa. Một ô nhịp có số chỉ nhịp lẻ giữ nguyên nửa phách của nó (7/8 in ba phách rưỡi mỗi ô nhịp). Trang của bản sao ghi rõ những gì bản kết xuất đã bỏ ra — các controller nó không phát, các nốt trống mà bộ trống không có tiếng — không bao giờ lặng lẽ bỏ qua. Một bài kiểm thử đọc cấu trúc các trang của ứng dụng và của chính các bản in trong video rồi đối chiếu chúng với nhau.","changelog.fa6958b17901":"<strong>Kéo bản sao vào DAW của bạn.</strong> Trang được đẩy ra mang một khung xanh chanh quanh clip, bên dưới có dòng <em>Kéo vào DAW</em> — chính khung là tay nắm. Nhấn bên trong khung và di chuyển 4 px, tệp của chính bản sao sẽ được kéo (kèm một bản in nhỏ trên con trỏ) vào FL Studio, Ableton, Reaper hoặc bất kỳ DAW nào nhận tệp. Không thể kéo gì cho đến khi trang ra hết; ở nơi không thể kéo, khung chuyển sang màu xám, nét đứt và đề xuất Lưu thành thay thế. Nhấn <code>Enter</code> trên trang sẽ mở Lưu thành hoặc hiện tệp trong thư mục của nó.","changelog.4da7005c5000":"<strong>Tiếng máy</strong>, được tổng hợp từ đầu cho chiếc máy photo này (đặt bản gốc, nắp, tiếng bíp, bắt đầu quét, một tiếng rè cho mỗi lượt đèn quét, đẩy trang ra) và được plugin trộn vào ngõ ra riêng của nó — không bao giờ qua thẻ HTML <code>&lt;audio&gt;</code> — ở mức −18 dB qua mức Monitor, im lặng khi DAW đang phát (ứng dụng độc lập không có transport DAW nào để phải im lặng), im lặng khi bounce ngoại tuyến, và không bao giờ thay thế âm thanh của track. Trong Cài đặt có bật/tắt, âm lượng, và lựa chọn “Im lặng khi DAW đang phát”.","changelog.f8fc9e0d2e58":"<strong>Màn hình cảm ứng</strong> cho biết máy đang làm gì, clip nó đang giữ, và mọi lời từ chối bằng ngôn ngữ của nhà sản xuất nhạc.","changelog.1a5ee7d7aabc":"<strong>Các cổng kiểm tra</strong> cho tất cả những điều đó, mỗi cổng đều được chứng kiến thất bại trước khi được tin dùng: bộ ba khớp nền (màu của bản kết xuất bằng đúng các token; ΔE2000 quanh hình bóng alpha của chính cỗ máy ở mọi giai đoạn với DPR 1 và 2; không có gì được vẽ giữa cỗ máy và nền), cổng START (tĩnh, plugin và Playwright), sự tương đồng bản in, các điểm ảnh của khung kéo, và các spec mới của nhánh ứng dụng chạy trong ứng dụng độc lập thật.","changelog.66b1e687636a":"<strong>Mã dùng chung</strong>: <code>freally-extract</code> (cửa giải mã và phân tích âm thanh), <code>freally-encode</code> (WAV, lấy mẫu lại, các đoạn khớp lưới DAW) và <code>freally-drag</code> (nguồn kéo gốc của hệ điều hành) được dùng từ MIDI Master ở <code>shared-v5</code>, cùng với <code>freally_library::audition::NoteRenderer</code>, các sự kiện controller của <code>read_facts</code>, và hook thả tệp của bộ điều hợp web view, việc đặt lại vị trí web view khi cửa sổ di chuyển và thanh tiêu đề trống của nó — tất cả được thêm ở thượng nguồn tại đó.","changelog.e7908191194e":"<strong>Biểu tượng là của chính chủ sở hữu</strong> — chữ <em>F</em> xanh chanh trên nền dạng sóng và piano roll — trên tệp thực thi, các gói plugin, biểu tượng Linux và macOS và trang tài liệu, thay cho biểu tượng tạm.","changelog.719f74499130":"<strong>Cửa sổ.</strong> Thanh tiêu đề của ứng dụng độc lập mang biểu tượng, tối màu và cùng màu với căn phòng, và không ghi gì cả: không có tiêu đề trên thanh tiêu đề của ứng dụng độc lập hay của cửa sổ plugin trong một DAW mà chú thích đã nêu tên Flipcopy, vì tên đang xoay ở phía trên cửa sổ đã nói điều đó. Tên xoay ấy lớn gấp đôi để đọc được trong nháy mắt, và được căn giữa phía máy photo của cửa sổ; bên cạnh đó, trình duyệt tệp chạy từ đỉnh cửa sổ xuống đến khu nghe thử.","changelog.120afa46c010":"Cầu nối nhận yêu cầu tới 2 MiB (một ảnh kéo); <code>host_info</code> cho biết ở đây có thể kéo trang hay không.","changelog.df29ffbf7480":"Trước khi thỏa thuận cấp phép được chấp nhận, trang chỉ có thể đọc ngôn ngữ giao diện và không gì khác, qua một lệnh riêng (<code>locale_get</code>); <code>prefs_get</code> chỉ trả lời khi thỏa thuận đã được chấp nhận.","changelog.bf4a28a43b62":"<strong>Di chuyển cửa sổ trên màn hình có tỉ lệ co giãn.</strong> Khi Windows được đặt ở 150%, kéo cửa sổ ứng dụng độc lập bằng thanh tiêu đề khiến nội dung bị vẽ lệch về phía sau cửa sổ một phần ba quãng đường, về phía góc trên bên trái màn hình, che mất mép phải và mép dưới cho đến khi cửa sổ được đưa về lại góc đó. Giờ đây nội dung luôn nằm đúng dưới cửa sổ dù nó được di chuyển đi đâu.","changelog.f246f03536b6":"<strong>Ứng dụng độc lập ở đúng tỉ lệ màn hình của bạn.</strong> Trên màn hình có tỉ lệ co giãn (150%), ứng dụng độc lập chạy như một chương trình kiểu cũ, không co giãn: Windows kéo giãn cửa sổ của nó trong khi trang bên trong vẽ theo điểm ảnh thật — gốc rễ của các lỗi lệch vị trí khi kéo và ở danh sách thả xuống được liệt kê ở đây. Giờ đây nó tự khai báo nhận biết DPI theo từng màn hình trước khi mở cửa sổ, giống ứng dụng độc lập của Freally MIDI Master và Freally Unloop, nên trang được vẽ sắc nét theo tỉ lệ màn hình và cửa sổ mở ra đúng kích thước dự định.","changelog.4d43aa80977a":"<strong>Danh sách ngôn ngữ mở ngay dưới ô của nó.</strong> Trên màn hình có tỉ lệ co giãn, danh sách thả xuống của hệ thống mở lệch xuống dưới và sang phải ô trong Cài đặt, ô càng xa góc cửa sổ thì lệch càng xa; giờ đây danh sách do chính Flipcopy vẽ, ngay dưới ô, theo phong cách tối của cửa sổ, và mỗi ngôn ngữ được viết bằng chữ viết của riêng nó.","changelog.a348e37f07eb":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-09-26\">2026-09-26</time></span><span class=\"release__title\">Nền móng &amp; xương sống CI</span>","changelog.8847996db9e9":"Sản phẩm trống mà mọi bậc sau đều xây dựng trên đó: nó tải được, cho âm thanh đi qua nguyên vẹn, hỏi về thỏa thuận cấp phép, mở cửa sổ tối của nó, và mọi cổng kiểm tra chất lượng đều chạy.","changelog.cc29ebe17a90":"<strong>Plugin, mọi định dạng từ một tệp nhị phân.</strong> Một plugin CLAP nih-plug với các điểm vào VST3 và AUv2 do <code>clap-wrapper</code> tạo ra (sạch về giấy phép: không dùng binding VST3 GPL), cùng <strong>ứng dụng độc lập</strong> — một ứng dụng desktop gốc có cửa sổ và thiết bị âm thanh riêng, không bao giờ là ứng dụng web. Âm thanh stereo vào và ra, một đầu vào nốt cho tính năng “Quét từ track” sau này, độ trễ bằng không, và âm thanh của track được cho đi qua <strong>nguyên từng bit</strong> (một bài kiểm tra null chứng minh điều đó). Một công tắc <strong>Bypass</strong> của host và một mức <strong>Monitor</strong> cho âm thanh mà chính Flipcopy sẽ thêm vào (tiếng máy và nghe thử, từ <code>v0.2.0</code>) — nó không bao giờ chạm vào track. Một trạng thái lưu có phiên bản, được giới hạn kích thước, được chuyển đổi khi nâng cấp và bị từ chối toàn bộ thay vì tải một nửa, nên một dự án bị hỏng không bao giờ làm sập host.","changelog.59616adfaedb":"<strong>Thỏa thuận cấp phép</strong> (<code>EULA.md</code>, có cấu trúc giống của Freally Oscillate) và cổng kiểm tra của nó: Flipcopy yêu cầu bạn chấp nhận ở lần mở đầu tiên và không làm gì cho đến khi bạn đồng ý — nó không đọc gì, không sao chép gì và không thêm gì vào track của bạn. Thỏa thuận được biên dịch vào plugin và được phục vụ từ đó, nút Đồng ý chờ cho đến khi văn bản được đọc đến hết, và câu trả lời của bạn được dùng chung cho mọi bản đang mở và ứng dụng độc lập. Một lần từ chối không lưu được sẽ báo rõ điều đó.","changelog.ed5631790156":"<strong>Cửa sổ</strong>, mở ở kích thước 1400 × 875 (kích thước của Freally Unloop) và co giãn đồng bộ đến mọi kích thước — mọi thứ giữ nguyên tỉ lệ, không có dải viền nào quanh nó — bên dưới một thanh tiêu đề nơi <em>Freally Flipcopy</em> và số phiên bản xoay quanh trục Y theo kiểu 3D, giống như của Freally Oscillate và Freally MIDI Master (và đứng yên khi bật giảm chuyển động): lớp vỏ tối với thanh trình duyệt và khu nghe thử ở phía đầu dòng, một thanh chia có thể kéo (260–420 px, dùng được cả phím mũi tên), và sân khấu — không có nền riêng, để máy photo sẽ đứng trong căn phòng mà không có đường nối nào xung quanh. Một chủ đề duy nhất, tối, và không có gì có thể tạo ra chủ đề thứ hai.","changelog.ccf91016802f":"<strong>Mười tám ngôn ngữ</strong> cho mọi thứ trong cửa sổ, lựa chọn được lưu theo từng máy tính và dùng chung cho mọi bản đang chạy; bố cục từ phải sang trái cho tiếng Ả Rập.","changelog.92d766745704":"<strong>Phông chữ Noto của Google</strong>, được đóng gói kèm theo giấy phép SIL Open Font License 1.1, với tệp giấy phép đi kèm bên cạnh.","changelog.b502e66ba7a3":"<strong>Trang tài liệu</strong>, được xây dựng giống trang của Freally Oscillate và chỉ có giao diện tối, bằng cùng mười tám ngôn ngữ (mỗi ngôn ngữ chỉ được tải khi người đọc chọn): trang chủ với chiếc thang phiên bản (được tạo từ <code>docs/ladder.json</code> và được một cổng kiểm tra giữ khớp với kế hoạch nội bộ), hai câu chuyện máy photo dựng bằng Blender trong “Xem nó sao chép”, tài liệu, nhật ký thay đổi này, và một trang tải xuống nói thẳng rằng chưa có gì để tải trước <code>v1.0.0</code>. Các câu chuyện phát kèm âm thanh, chỉ khi bạn nhấn chữ START xiên trên phím xanh lá của máy photo (hoặc nút phát), và dừng lại ở khung hình đầu tiên khi kết thúc hoặc bị dừng; câu chuyện âm thanh → MIDI in mỗi lớp một trang — MIDI Giai điệu, MIDI Hợp âm, MIDI Dòng bass và MIDI Đối điệu — lần lượt lên một xấp trong khay, mỗi trang đóng khung xanh chanh với <em>Kéo vào DAW</em> bên dưới.","changelog.96a59e69b7f8":"<strong>Văn bản luôn nằm gọn trong khung chứa</strong> ở cả 18 ngôn ngữ, ở cửa sổ mặc định và cửa sổ nhỏ nhất (một bước kiểm tra Playwright trên mọi nhãn).","changelog.495bcdf8956e":"<strong>Các cổng kiểm tra</strong>, mỗi cổng đều được chứng kiến thất bại trước khi được tin dùng: định dạng mã, clippy, mọi bài kiểm thử, kiểm tra kiểu, lint, cổng ngôn ngữ (18 danh mục, khóa và placeholder giống hệt nhau, thật sự được dịch), lint CSS logic, design token và độ tương phản, chỉ giao diện tối, danh sách cấm (không AI, không mạng, không đo lường từ xa), kiểm tra giấy phép, cổng crate dùng chung (dùng lại, không bao giờ fork), tên sản phẩm (không bao giờ dùng thương hiệu của hãng sản xuất máy photo), độ lệch binding, chiếc thang, không có bản tải xuống trước 1.0, ngân sách tài nguyên, <code>clap-validator</code> và <code>pluginval</code> ở mức nghiêm ngặt 10, CI cục bộ trên Windows và trong Docker cho Linux, và Playwright trên hai nhánh — trình duyệt và cửa sổ ứng dụng độc lập thật.","changelog.8f6fb4eb7f42":"Bảo mật","changelog.09dd8d0ea4e1":"Giao diện chỉ tải trang đã được biên dịch vào tệp nhị phân, dưới một Content Security Policy nghiêm ngặt; cầu nối của nó chỉ trả lời yêu cầu JSON <code>POST</code> của chính trang đó, từ chối mọi thứ trên 64 KiB và mọi đường dẫn chứa <code>..</code>, và trước khi thỏa thuận được chấp nhận thì chỉ trả lời một danh sách lệnh được cho phép. Bản dựng phát hành không mở DevTools và không mở cổng gỡ lỗi từ xa.","changelog.e06fbd4d3359":"Không có mã mạng trong plugin hay ứng dụng độc lập, được trình biên dịch (<code>clippy.toml</code>) và đồ thị phụ thuộc (<code>scripts/check-denylist.mjs</code>) kiểm tra.","changelog.70e17daefb45":"Các tệp mà Flipcopy lưu trong thư mục dữ liệu ứng dụng của bạn (câu trả lời cho thỏa thuận và các tùy chọn) được đọc với giới hạn kích thước và được ghi nguyên tử, nên một tệp bị hỏng hoặc bị sửa tay sẽ được tải như giá trị mặc định và một sự cố không bao giờ để lại nửa tệp."};
